mapper.select:
SELECT T.*, IF(sysProjectFunctionDefaultLabel is not null, 1, 0) sysProjectFunctionDefault FROM ( SELECT sp.*, sdi.sys_dict_item_name sysProjectDictItemLabel, sdi.sys_dict_item_code sysProjectDictItemCode, (SELECT group_concat(sdi.sys_dict_item_name) FROM sys_project_default spd INNER JOIN sys_dict_item sdi ON spd.sys_project_default_type = sdi.sys_dict_item_id WHERE spd.sys_project_id = sp.sys_project_id) sysProjectFunctionDefaultLabel, (SELECT group_concat(sdi.sys_dict_item_id) FROM sys_project_default spd INNER JOIN sys_dict_item sdi ON spd.sys_project_default_type = sdi.sys_dict_item_id WHERE spd.sys_project_id = sp.sys_project_id) sysProjectFunctionDefaultIds FROM sys_project sp INNER JOIN sys_dict_item sdi ON sdi.sys_dict_item_id = sp.sys_project_vender
AND sys_project_id = #{request.sysProjectId}
AND sys_project_group = #{request.sysProjectGroup}
AND sys_project_vender = #{request.sysProjectVender}
AND FIND_IN_SET(#{request.sysProjectFunction}, sys_project_function)
) T ORDER BY sysProjectFunctionDefaultLabel DESC
